//! GitHub Actions publisher generated by `pixi-sandbox init`.

use super::GENERATED_MARKER;
use crate::release::PIXI_SANDBOX_REPO;

/// Inputs whose values vary independently of the reviewed workflow template.
#[derive(Debug, Clone, Copy)]
pub struct GithubWorkflowOptions<'a> {
    /// Exact pixi-sandbox package and standalone-bootstrap version.
    pub version: &'a str,
    /// Sandbox plan path passed to `pixi-sandbox plan` in the consumer repository.
    pub config_path: &'a str,
}

fn shell_word(value: &str) -> String {
    if !value.is_empty()
        && value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || b"_./-".contains(&byte))
    {
        value.to_string()
    } else {
        format!("'{}'", value.replace('\'', "'\"'\"'"))
    }
}

/// Render the connected-side publisher workflow.
///
/// The connected CLI comes from the native prefix.dev package. A separately checksum-verified
/// standalone release binary is embedded as the transport bootstrap: package binaries are allowed
/// to use system linkage, while an airlock bootstrap must satisfy the stricter linkage policy.
#[must_use]
pub fn render_github_workflow(options: GithubWorkflowOptions<'_>) -> String {
    let template = r#"# __GENERATED_MARKER__
# __VERSION_STAMP__
name: publish sandbox

on:
  workflow_dispatch:
  push:
    branches: [main]

permissions:
  contents: write

env:
  PIXI_SANDBOX_VERSION: __VERSION__
  PIXI_SANDBOX_CHANNEL: https://prefix.dev/archont561/archont561

jobs:
  plan:
    runs-on: ubuntu-latest
    outputs:
      matrix: ${{ steps.plan.outputs.matrix }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - uses: prefix-dev/setup-pixi@d3f436a425481402e6a95a1d1fc10331c708cd9e # v0.10.2
        with:
          run-install: false
      - name: Install pixi-sandbox CLI
        shell: bash
        run: >-
          pixi global install
          --channel "$PIXI_SANDBOX_CHANNEL"
          --channel conda-forge
          "pixi-sandbox==${PIXI_SANDBOX_VERSION}"
      - id: plan
        shell: bash
        run: echo "matrix=$(pixi-sandbox plan --config __CONFIG_PATH__ --json)" >> "$GITHUB_OUTPUT"

  publish:
    needs: plan
    strategy:
      fail-fast: false
      # `include:` nested under `matrix:`, not `matrix:` itself. `plan --json` emits
      # {"schema":1,"include":[...]}, and Actions requires strategy.matrix to be an object.
      matrix:
        include: ${{ fromJSON(needs.plan.outputs.matrix).include }}
    runs-on: ${{ matrix.runner }}
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          persist-credentials: false
      - uses: prefix-dev/setup-pixi@d3f436a425481402e6a95a1d1fc10331c708cd9e # v0.10.2
        with:
          run-install: false
      - name: Install pixi-sandbox CLI
        shell: bash
        run: >-
          pixi global install
          --channel "$PIXI_SANDBOX_CHANNEL"
          --channel conda-forge
          "pixi-sandbox==${PIXI_SANDBOX_VERSION}"

      # Consumer workflows embed the released, checksum-verified standalone binary. Building
      # from the checkout would incorrectly assume the consumer has pixi-sandbox's source tree
      # and its `package` environment; the checked-out tree belongs to the consumer project.
      - name: Download released pixi-sandbox
        id: bootstrap-unix
        if: runner.os != 'Windows'
        shell: bash
        run: |
          case "${{ matrix.platform }}" in
            linux-64) asset=pixi-sandbox-x86_64-unknown-linux-musl ;;
            linux-aarch64) asset=pixi-sandbox-aarch64-unknown-linux-musl ;;
            osx-64) asset=pixi-sandbox-x86_64-apple-darwin ;;
            osx-arm64) asset=pixi-sandbox-aarch64-apple-darwin ;;
            *) echo "::error::unsupported release platform: ${{ matrix.platform }}"; exit 2 ;;
          esac
          base="$GITHUB_SERVER_URL/__RELEASE_REPO__/releases/download/v${PIXI_SANDBOX_VERSION}"
          path="$RUNNER_TEMP/$asset"
          curl --fail --location --silent --show-error "$base/$asset" --output "$path"
          curl --fail --location --silent --show-error "$base/SHA256SUMS" --output "$RUNNER_TEMP/SHA256SUMS"
          grep "  $asset$" "$RUNNER_TEMP/SHA256SUMS" | sha256sum --check --status -
          chmod +x "$path"
          echo "path=$path" >> "$GITHUB_OUTPUT"

      - name: Download released pixi-sandbox
        id: bootstrap-windows
        if: runner.os == 'Windows'
        shell: pwsh
        run: |
          $asset = switch ('${{ matrix.platform }}') {
            'win-64' { 'pixi-sandbox-x86_64-pc-windows-msvc.exe' }
            default { throw "unsupported release platform: ${{ matrix.platform }}" }
          }
          $base = "$env:GITHUB_SERVER_URL/__RELEASE_REPO__/releases/download/v$env:PIXI_SANDBOX_VERSION"
          $path = Join-Path $env:RUNNER_TEMP $asset
          Invoke-WebRequest -UseBasicParsing "$base/$asset" -OutFile $path
          Invoke-WebRequest -UseBasicParsing "$base/SHA256SUMS" -OutFile (Join-Path $env:RUNNER_TEMP 'SHA256SUMS')
          $expected = (Get-Content (Join-Path $env:RUNNER_TEMP 'SHA256SUMS') | Where-Object { $_ -match "  $([regex]::Escape($asset))$" }).Split()[0]
          if ((Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $expected.ToLowerInvariant()) { throw "SHA256 mismatch for $asset" }
          "path=$path" | Out-File -FilePath $env:GITHUB_OUTPUT -Append -Encoding utf8

      - name: Pack, verify, and publish
        if: runner.os != 'Windows'
        shell: bash
        env:
          ENVIRONMENTS: ${{ matrix.environments }}
          PLATFORM: ${{ matrix.platform }}
          BRANCH: ${{ matrix.branch }}
          CARGO_VENDOR: ${{ matrix.cargo_vendor }}
          SELF_BIN: ${{ steps.bootstrap-unix.outputs.path }}
          REMOTE: ${{ github.server_url }}/${{ github.repository }}.git
          PUSH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          IFS=',' read -ra ENVS <<< "$ENVIRONMENTS"
          for ENVIRONMENT in "${ENVS[@]}"; do
            pixi install --frozen -e "${ENVIRONMENT//[[:space:]]/}"
          done
          TRANSPORT="$RUNNER_TEMP/pixi-sandbox-transport"
          rm -rf "$TRANSPORT"
          CARGO_VENDOR_ARG=
          if [ "$CARGO_VENDOR" = true ]; then CARGO_VENDOR_ARG=--cargo-vendor; fi
          "$SELF_BIN" pack \
            --repo-root . \
            --envs "$ENVIRONMENTS" \
            --output-dir "$TRANSPORT" \
            --platform "$PLATFORM" \
            --fetch-tools \
            --self-bin "$SELF_BIN" \
            $CARGO_VENDOR_ARG
          "$SELF_BIN" doctor --branch-location "$TRANSPORT" --verify
          BASIC_AUTH=$(printf 'x-access-token:%s' "$PUSH_TOKEN" | base64 | tr -d '\r\n')
          export GIT_CONFIG_COUNT=1
          export GIT_CONFIG_KEY_0=http.extraheader
          export GIT_CONFIG_VALUE_0="AUTHORIZATION: basic $BASIC_AUTH"
          "$SELF_BIN" publish --input-dir "$TRANSPORT" --branch-name "$BRANCH" --remote "$REMOTE"

      - name: Pack, verify, and publish
        if: runner.os == 'Windows'
        shell: pwsh
        env:
          ENVIRONMENTS: ${{ matrix.environments }}
          PLATFORM: ${{ matrix.platform }}
          BRANCH: ${{ matrix.branch }}
          CARGO_VENDOR: ${{ matrix.cargo_vendor }}
          SELF_BIN: ${{ steps.bootstrap-windows.outputs.path }}
          REMOTE: ${{ github.server_url }}/${{ github.repository }}.git
          PUSH_TOKEN: ${{ github.token }}
        run: |
          $ErrorActionPreference = 'Stop'
          $PSNativeCommandUseErrorActionPreference = $true
          foreach ($environment in ($env:ENVIRONMENTS -split ',')) {
            pixi install --frozen -e $environment.Trim()
          }
          $transport = Join-Path $env:RUNNER_TEMP 'pixi-sandbox-transport'
          Remove-Item -Recurse -Force $transport -ErrorAction SilentlyContinue
          $packArgs = @('pack', '--repo-root', '.', '--envs', $env:ENVIRONMENTS, '--output-dir', $transport, '--platform', $env:PLATFORM, '--fetch-tools', '--self-bin', $env:SELF_BIN)
          if ($env:CARGO_VENDOR -eq 'true') { $packArgs += '--cargo-vendor' }
          & $env:SELF_BIN @packArgs
          & $env:SELF_BIN doctor --branch-location $transport --verify
          $bytes = [System.Text.Encoding]::UTF8.GetBytes("x-access-token:$env:PUSH_TOKEN")
          $basic = [System.Convert]::ToBase64String($bytes)
          $env:GIT_CONFIG_COUNT = '1'
          $env:GIT_CONFIG_KEY_0 = 'http.extraheader'
          $env:GIT_CONFIG_VALUE_0 = "AUTHORIZATION: basic $basic"
          & $env:SELF_BIN publish --input-dir $transport --branch-name $env:BRANCH --remote $env:REMOTE
"#;
    template
        .replace("__GENERATED_MARKER__", GENERATED_MARKER)
        .replace("__VERSION_STAMP__", &super::version_stamp_line(options.version))
        .replace("__VERSION__", options.version)
        .replace("__CONFIG_PATH__", &shell_word(options.config_path))
        .replace("__RELEASE_REPO__", PIXI_SANDBOX_REPO)
}
